const id=location.pathname.match(/^\/g\/([a-f0-9]{32})$/)?.[1],status=document.querySelector('.present-status'),frame=document.querySelector('iframe');
async function api(path,{method='GET',body,secret}={}){const response=await fetch(path,{method,headers:{...(secret?{Authorization:'Bearer '+secret}:{}),...(body?{'Content-Type':'application/json'}:{})},body:body?JSON.stringify(body):undefined,cache:'no-store'});const data=await response.json();if(!response.ok){const error=Error(data.error||'Não foi possível abrir agora.');error.status=response.status;throw error;}return data;}
const retry=document.querySelector('.present-retry'),actions=document.querySelector('.present-actions'),stage=document.querySelector('.gift-stage'),fullscreen=document.querySelector('.present-fullscreen');let readyTimer,awaitingReady=false;
function screenState(){const expanded=!!document.fullscreenElement||stage.classList.contains('expanded');fullscreen.textContent=expanded?'Voltar':'Tela cheia';fullscreen.setAttribute('aria-label',expanded?'Sair da tela cheia':'Ver presente em tela cheia');fullscreen.setAttribute('aria-pressed',String(expanded));}
async function exitExpanded(){if(document.fullscreenElement)try{await document.exitFullscreen();}catch{}stage.classList.remove('expanded');document.body.classList.remove('gift-expanded');screenState();}
fullscreen.addEventListener('click',async()=>{if(document.fullscreenElement||stage.classList.contains('expanded'))return exitExpanded();try{if(!stage.requestFullscreen)throw Error();await stage.requestFullscreen();}catch{stage.classList.add('expanded');document.body.classList.add('gift-expanded');}screenState();});document.addEventListener('fullscreenchange',screenState);document.addEventListener('keydown',event=>{if(event.key==='Escape'&&stage.classList.contains('expanded'))exitExpanded();});
document.querySelector('.present-copy').addEventListener('click',async()=>{const link=location.origin+location.pathname;try{await navigator.clipboard.writeText(link);status.textContent='Link do presente copiado.';}catch{const input=document.querySelector('.share-link');document.querySelector('.share-fallback').hidden=false;input.value=link;input.focus();input.select();status.textContent='Selecione e copie o link abaixo.';}});
document.querySelector('.present-rsvp-link').addEventListener('click',async()=>{await exitExpanded();const section=document.querySelector('.rsvp');section.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});section.querySelector('h2').focus({preventScroll:true});});document.querySelector('.back-to-gift').addEventListener('click',()=>{stage.scrollIntoView({behavior:'instant',block:'start'});fullscreen.focus({preventScroll:true});});
function failed(message,preserveContent=false){clearTimeout(readyTimer);awaitingReady=preserveContent;status.textContent=message;stage.classList.add('has-error');document.querySelector('.gift-loading-text').textContent='Seu presente ainda não abriu.';retry.hidden=false;actions.hidden=!document.querySelector('.present-download').getAttribute('href');frame.hidden=!preserveContent;stage.classList.toggle('content-ready',preserveContent);if(preserveContent)frame.removeAttribute('tabindex');fullscreen.disabled=!preserveContent;}
function loadContent(){clearTimeout(readyTimer);awaitingReady=true;stage.classList.remove('content-ready','has-error');document.querySelector('.gift-loading-text').textContent='Um carinho está chegando.';frame.setAttribute('tabindex','-1');fullscreen.disabled=false;status.textContent='Carregando seu presente… Aguarde um instante.';retry.hidden=true;actions.hidden=true;document.querySelector('.present-fullscreen').hidden=false;frame.hidden=false;frame.src='/api/presents/'+id+'/content';readyTimer=setTimeout(()=>failed('Não conseguimos confirmar a abertura. Se o presente não apareceu, tente novamente ou baixe a cópia.',true),30000);}
addEventListener('message',event=>{if(event.source!==frame.contentWindow||!awaitingReady)return;if(event.data?.type==='capimimo:ready'){clearTimeout(readyTimer);awaitingReady=false;stage.classList.add('content-ready');stage.classList.remove('has-error');frame.removeAttribute('tabindex');fullscreen.disabled=false;status.textContent='Abra seu mimo e leia no seu ritmo.';actions.hidden=false;retry.hidden=true;document.querySelector('.present-fullscreen').hidden=false;}else if(event.data?.type==='capimimo:error')failed('Não foi possível abrir o presente agora. Toque em “Tentar abrir novamente”.');});
frame.addEventListener('error',()=>failed('Não foi possível carregar o presente. Confira sua conexão e tente novamente.'));retry.addEventListener('click',()=>{if(!frame.getAttribute('src'))location.reload();else if(id)loadContent();});
async function open(){if(!id)throw Error('O endereço deste presente está incompleto.');const data=await api('/api/presents/'+id);document.querySelector('h1').textContent=data.recipient?'Um mimo para '+data.recipient+'.':'Tem um mimo para você.';document.querySelector('.test-notice').hidden=!data.test;loadContent();if(data.rsvp)document.querySelector('.access-note').textContent='Para confirmar presença, use o convite individual enviado a você. A confirmação aparece no final desta página.';document.querySelector('.present-download').href='/api/presents/'+id+'/download';
 const guestId=new URLSearchParams(location.search).get('convidado'),secret=new URLSearchParams(location.hash.slice(1)).get('responder');if(data.rsvp&&/^[a-f0-9]{32}$/.test(guestId||'')&&/^[a-f0-9]{64}$/.test(secret||'')){
  const path='/api/presents/'+id+'/guests/'+guestId,section=document.querySelector('.rsvp'),form=section.querySelector('form'),rsvpStatus=section.querySelector('.rsvp-status'),rsvpLink=document.querySelector('.present-rsvp-link');section.hidden=false;rsvpLink.hidden=false;const retryGuest=document.createElement('button');retryGuest.type='button';retryGuest.className='rsvp-retry';retryGuest.textContent='Tentar carregar meu convite';retryGuest.hidden=true;section.querySelector('.back-to-gift').before(retryGuest);retryGuest.addEventListener('click',()=>loadGuest());async function loadGuest(){retryGuest.hidden=true;section.querySelector('.guest-name').textContent='';for(const control of form.querySelectorAll('label,button'))control.hidden=true;for(const control of form.elements)control.disabled=true;rsvpStatus.textContent='Conferindo seu convite individual…';try{const guest=await api(path,{secret});rsvpLink.textContent='Responder ao convite ↓';rsvpStatus.textContent='';for(const control of form.querySelectorAll('label,button'))control.hidden=false;for(const control of form.elements)control.disabled=false;section.querySelector('.guest-name').textContent='Este convite é para '+guest.name+'.';form.elements.count.max=guest.allowedCount;form.elements.count.value=guest.attendingCount||1;form.elements.status.value=guest.status==='declined'?'declined':'accepted';let submitting=false;const update=()=>{const declined=form.elements.status.value==='declined';section.querySelector('.attending-label').hidden=declined;form.elements.count.disabled=declined||submitting;if(!declined&&!form.elements.count.checkValidity())form.elements.count.value='1';};form.elements.status.addEventListener('change',update);update();if(guest.status!=='invited')section.querySelector('.rsvp-status').textContent='Sua resposta já está salva. Você pode atualizá-la.';form.addEventListener('submit',async event=>{event.preventDefault();if(submitting||!form.reportValidity())return;const button=form.querySelector('button'),answer=form.elements.status.value,count=form.elements.count.value,payload={status:answer,attendingCount:answer==='declined'?0:Number(count)};const focusOwner=form.contains(document.activeElement)?document.activeElement:null;rsvpStatus.tabIndex=-1;rsvpStatus.textContent='Enviando sua resposta…';if(focusOwner)rsvpStatus.focus({preventScroll:true});submitting=true;form.setAttribute('aria-busy','true');button.disabled=true;form.elements.status.disabled=true;form.elements.count.disabled=true;try{const result=await api(path,{method:'PUT',secret,body:payload});rsvpStatus.textContent=result.status==='accepted'?'Presença confirmada! Sua resposta foi recebida.':'Resposta recebida. Obrigado por avisar.';}catch(e){rsvpStatus.textContent=e.message;}finally{form.elements.status.value=answer;form.elements.count.value=count;submitting=false;form.setAttribute('aria-busy','false');form.elements.status.disabled=false;button.disabled=false;update();if(focusOwner&&document.activeElement===rsvpStatus)(focusOwner.disabled?button:focusOwner).focus({preventScroll:true});}});
  }catch(error){rsvpLink.textContent='Ver situação do convite ↓';rsvpStatus.textContent=[401,403,404,410].includes(error.status)?'Este link de confirmação não está mais disponível. Peça um novo convite individual a quem enviou. Você pode continuar vendo o presente acima.':'Não foi possível carregar a confirmação de presença. Confira sua conexão e tente novamente. O presente continua disponível acima.';retryGuest.hidden=[401,403,404,410].includes(error.status);}}await loadGuest();
 }
}
open().catch(e=>{failed(e.message);document.querySelector('.access-note').textContent='Confira o endereço ou fale com quem enviou o mimo.';});
